func (s *Store) Get(id string) (*Item, error) {
    if id == "" {
        return nil, errors.New("store: empty id")            // guard: bad input
    }
    it, err := s.load(id)
    if err != nil {
        return nil, fmt.Errorf("store: get %s: %w", id, err)  // guard: error-first
    }
    return normalize(it), nil                                 // happy path stays flat
}
